 if(bt==='knife')f+=`<path d="M${x0+L*.25} ${cy+H*.7}Q${x0+L*.6} ${cy+H*1.6} ${x1} ${cy+2}L${x1-6} ${cy+H*.3}Z" fill="${c2}" opacity=".7"/>`;
